// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address actor, uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(actor != address(0));
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);
        vm.deal(actor, depositAmount);
        vm.startPrank(actor);
        c.addToBalance{value: depositAmount}();
        vm.stopPrank();

        uint256 balanceBefore = address(c).balance;
        uint256 actorBalance = c.getBalance(actor);
        vm.prank(actor);
        try c.withdrawBalance() { } catch { }
        uint256 balanceAfter = address(c).balance;

        assertTrue(balanceAfter == balanceBefore - actorBalance);
    }
}
